mapper.select:
SELECT s.WORKFLOW_ID, d.WORKFLOW_NAME, s.CRON, s.ENABLE_FLAG, s.CREATED_BY, s.CREATION_DATE, s.LAST_UPDATED_BY, s.LAST_UPDATE_DATE FROM WF_SCHEDULER s LEFT JOIN WF_DEFINITIONS d ON s.WORKFLOW_ID = d.WORKFLOW_ID
AND s.WORKFLOW_ID LIKE #{workflowId}
AND d.WORKFLOW_NAME LIKE #{workflowName}
